// Helper functions

// チームIDマップ（O(n)→O(1)）
let _teamMap: Map<string, Team> | null = null;
function getTeamMap(): Map<string, Team> {
  if (!_teamMap) _teamMap = new Map(teams.map((t) => [t.id, t]));
  return _teamMap;
}

// プレイヤーIDマップ（O(n×m)→O(1)）
let _playerMap: Map<string, { player: Player; team: Team }> | null = null;
function getPlayerMap(): Map<string, { player: Player; team: Team }> {
  if (!_playerMap) {
    _playerMap = new Map();
    for (const team of teams) {
      for (const player of team.players) {
        _playerMap.set(player.id, { player, team });
      }
    }
  }
  return _playerMap;
}

export function getTeamById(id: string): Team | undefined {
  return getTeamMap().get(id);
}

export function getTeamsByGroup(group: string): Team[] {
  return teams.filter((t) => t.group === group);
}

export function getGroups(): string[] {
  return [...new Set(teams.map((t) => t.group).filter(Boolean))].sort();
}

export function getPlayerById(playerId: string): { player: Player; team: Team } | undefined {
  const fromTeams = getPlayerMap().get(playerId);
  if (fromTeams) return fromTeams;

  // Also search the Japan squad (march 2026 call-up)
  const squadPlayer = japanSquad2026WC.find((p) => p.id === playerId);
  if (!squadPlayer) return undefined;

  const japanTeam = getTeamMap().get("japan");
  if (!japanTeam) return undefined;

  // Convert JapanSquadPlayer to Player format
  const player: Player = {
    id: squadPlayer.id!,
    name: squadPlayer.name,
    nameJa: squadPlayer.nameJa,
    number: 0,
    position: squadPlayer.position,
    club: squadPlayer.club,
    birthDate: squadPlayer.birthDate,
    age: squadPlayer.age,
    caps: 0,
    goals: 0,
    height: squadPlayer.height,
    description: squadPlayer.description,
  };

  return { player, team: japanTeam };
}

export function getAllPlayers(): { player: Player; team: Team }[] {
  return Array.from(getPlayerMap().values());
}
